for (const nm of newCitiesMeta) {
  const idx = cities.findIndex(c => c.id === nm.id);
  if (idx >= 0) {
    cities[idx] = { ...cities[idx], ...nm };
  } else {
    cities.push(nm);
  }
}

// Update existing HP cities
for (const city of cities) {
  if (city.state_id === 'himachal-pradesh') {
    if (hpCityCounts[city.id]) {
      city.places_count = hpCityCounts[city.id];
    } else if (city.id === 'kangra') {
      city.places_count = 0;
    }
  }
}

fs.writeFileSync(citiesPath, JSON.stringify(cities, null, 2), 'utf-8');
console.log(`✓ Updated data/cities.json with 10 Himachal Pradesh cities and exact place counts.`);

// -------------------------------------------------------------
// 3. UPDATE data/states.json
// -------------------------------------------------------------
const statesPath = 'data/states.json';
const states = JSON.parse(fs.readFileSync(statesPath, 'utf-8'));
const hpState = states.find(s => s.id === 'himachal-pradesh');
if (hpState) {
  hpState.total_attractions = 20;
  hpState.total_cities = 10;
  hpState.status = 'verified';
  hpState.official_tourism_url = 'https://himachaltourism.gov.in';
}
fs.writeFileSync(statesPath, JSON.stringify(states, null, 2), 'utf-8');
console.log(`✓ Updated data/states.json (Himachal Pradesh total_attractions = 20, total_cities = 10)`);

// -------------------------------------------------------------
