      tagline: `Destination in Himachal Pradesh`,
      description: cityMeta?.description || `Explore ${cid} in Himachal Pradesh`,
      hero_image_url: cityMeta?.hero_image_url || 'https://images.unsplash.com/photo-1597074866923-dc0589150358?w=1200&auto=format&fit=crop&q=80',
